<script setup lang="ts">
import type {ResourceData} from '../../../../shared/contracts';
const props=defineProps<{modelValue:ResourceData}>();const emit=defineEmits<{'update:modelValue':[ResourceData]}>();
function change(key:keyof ResourceData,event:Event){const value=(event.target as HTMLInputElement).value;emit('update:modelValue',{...props.modelValue,[key]:value||(key==='usageInstructions'?'':null)});}
</script>
<template><fieldset><legend>资源来源与使用范围</legend><label>提供方式<select :value="modelValue.mode" @change="change('mode',$event)"><option value="external">链接原出处</option><option value="download">本站提供下载</option></select></label><p class="notice">改为链接原出处时，本次保存会一并移除资源文件关联，归档原件仍保留。上传不代表获得再分发许可。</p><label>来源网址<input :value="modelValue.sourceUrl" maxlength="2048" placeholder="https://…" @input="change('sourceUrl',$event)"></label><label>作者 / 署名<input :value="modelValue.author" maxlength="200" @input="change('author',$event)"></label><label>许可证名称（可选）<input :value="modelValue.licenseName" maxlength="200" @input="change('licenseName',$event)"></label><label>再分发许可<select :value="modelValue.redistribution" @change="change('redistribution',$event)"><option value="unknown">尚未确认</option><option value="allowed">允许再分发</option><option value="forbidden">禁止再分发</option></select></label><label>许可依据说明<textarea :value="modelValue.permissionNote" maxlength="2000" @input="change('permissionNote',$event)"/></label><label>用途与使用说明<textarea :value="modelValue.usageInstructions" maxlength="2000" @input="change('usageInstructions',$event)"/></label><label>修改说明（可选）<textarea :value="modelValue.modificationNote" maxlength="2000" @input="change('modificationNote',$event)"/></label><label>版本（可选）<input :value="modelValue.versionLabel" maxlength="80" @input="change('versionLabel',$event)"></label></fieldset></template>
<style scoped>fieldset{border:1px solid var(--line);border-radius:10px;padding:16px;min-width:0;margin:20px 0}label{display:grid;gap:6px;margin:14px 0}textarea{min-height:90px}</style>
